// Verify HMAC-SHA256 signature from Convex. Throws => execution fails (visible via error workflow, Convex retries).
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not configured');

const headers = $input.first().json.headers;
const body = $input.first().json.body;
const ts = headers['x-lendloop-timestamp'];
const sig = (headers['x-lendloop-signature'] || '').replace('sha256=', '');

// Reject stale requests (replay protection): 5 minute window.
if (!ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) throw new Error('Stale or missing timestamp');

// Convex signs `${ts}.${compact JSON body}`; JSON.stringify of the parsed body reproduces it.
const expected = crypto.createHmac('sha256', secret).update(`${ts}.${JSON.stringify(body)}`).digest('hex');

const a = Buffer.from(expected, 'hex');
const b = Buffer.from(sig, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Invalid signature');

return [{ json: body }];

// Build a message using only the minimal fields in the payload.
const p = $input.first().json;
const msgs = {
  request_created: `${p.otherPartyName} wants to borrow your ${p.toolName} (${p.startDate} -> ${p.endDate}).`,
  request_approved: `${p.otherPartyName} approved your request for ${p.toolName} (${p.startDate} -> ${p.endDate}).`,
  request_declined: `${p.otherPartyName} declined your request for ${p.toolName}.`,
  loan_returned: `${p.toolName} was marked as returned. Thanks for using LendLoop!`,
};
return [{ json: {
  to: p.recipient.email,
  name: p.recipient.name,
  subject: `LendLoop: ${p.event.replace('_', ' ')}`,
  text: msgs[p.event] || 'Your LendLoop request was updated.',
  idempotencyKey: p.idempotencyKey,
} }];

// MOCK notification: logged only. Swap this node for Email / Slack / Discord in production.
const m = $input.first().json;
console.log(`[NOTIFY] to=${m.name} <${m.to}> | ${m.subject} | ${m.text}`);
return [{ json: { ok: true, idempotencyKey: m.idempotencyKey } }];
